const config = $('Configuracion').item.json;
const tableItems = $input.all();
let contexto = '';
const fanpages = tableItems.filter(function(i) { return i.json.nombre; });
if (fanpages.length > 0) {
  contexto = fanpages.map(function(i) { return '- ' + i.json.nombre + ' | Estilo: ' + i.json.estilo_visual + ' | Tema: ' + i.json.subtema; }).join('\n');
} else {
  contexto = 'Aun no hay fanpages creadas. Genera la primera.';
}
var finalPrompt = config.system_prompt + '\n\nFANPAGES YA CREADAS (NO repitas conceptos, nombres ni estilos similares):\n' + contexto;
return [{ json: { prompt_completo: finalPrompt } }];
